package com.companages.service;
import com.companages.dto.*; import com.companages.dto.PositionDtos.*; import com.companages.entity.*; import com.companages.exception.ResourceNotFoundException; import com.companages.repository.PositionRepository; import jakarta.persistence.criteria.Predicate; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class PositionService { private final PositionRepository positions; private final OrganizationAccessService access; private final ActivityService activities; private final NotificationService notifications; public PositionService(PositionRepository p,OrganizationAccessService a,ActivityService l,NotificationService n){positions=p;access=a;activities=l;notifications=n;}
 @Transactional public Response create(Long oid,Request r){Member actor=access.requireAdmin(oid);Position p=new Position();p.setName(r.name().trim());p.setDescription(r.description());p.setLevel(r.level());p.setOrganization(actor.getOrganization());p=positions.save(p);activities.record(actor.getOrganization(),ActivityAction.JOB_POSITION_CHANGED,"Position",p.getId(),p.getName());if(actor.getUser()!=null)notifications.create(actor.getUser(),actor.getOrganization(),"POSITION_CREATED","Position created",p.getName()+" is now available for assignment.","/positions");return Mappers.position(p);}
 @Transactional(readOnly=true) public List<Response> list(Long oid){access.requireMember(oid);return positions.findAllByOrganizationIdOrderByName(oid).stream().map(Mappers::position).toList();} @Transactional(readOnly=true) public PageResponse<Response> search(Long oid,String search,RecordStatus status,Pageable pageable){access.requireMember(oid);String term=search==null||search.isBlank()?null:search.trim().toLowerCase();Specification<Position> spec=(root,q,cb)->{List<Predicate> p=new ArrayList<>();p.add(cb.equal(root.get("organization").get("id"),oid));if(term!=null)p.add(cb.like(cb.lower(root.get("name")),"%"+term+"%"));if(status!=null)p.add(cb.equal(root.get("status"),status));return cb.and(p.toArray(Predicate[]::new));};return PageResponse.from(positions.findAll(spec,pageable),Mappers::position);} @Transactional(readOnly=true) public Response get(Long oid,Long id){access.requireMember(oid);return Mappers.position(require(oid,id));}
 @Transactional public Response update(Long oid,Long id,Request r){Member actor=access.requireAdmin(oid);Position p=require(oid,id);p.setName(r.name().trim());p.setDescription(r.description());p.setLevel(r.level());activities.record(actor.getOrganization(),ActivityAction.JOB_POSITION_CHANGED,"Position",p.getId(),p.getName());return Mappers.position(p);} @Transactional public void delete(Long oid,Long id){Member actor=access.requireAdmin(oid);Position p=require(oid,id);p.setStatus(RecordStatus.ARCHIVED);activities.record(actor.getOrganization(),ActivityAction.JOB_POSITION_CHANGED,"Position",p.getId(),"Archived "+p.getName());} @Transactional public void restore(Long oid,Long id){Member actor=access.requireAdmin(oid);Position p=require(oid,id);p.setStatus(RecordStatus.ACTIVE);activities.record(actor.getOrganization(),ActivityAction.JOB_POSITION_CHANGED,"Position",p.getId(),"Restored "+p.getName());} Position require(Long oid,Long id){return positions.findByIdAndOrganizationId(id,oid).orElseThrow(()->new ResourceNotFoundException("Position not found"));}}
